import subprocess, json
deploys = subprocess.check_output(['kubectl','get','deploy','-n','astronomy-shop','-o','json']).decode()
d = json.loads(deploys)
for dep in d['items']:
    name = dep['metadata']['name']
    for c in dep['spec']['template']['spec']['containers']:
        envs = c.get('env',[])
        seen = {}
        for e in envs:
            n = e['name']
            v = e.get('value', '<from>')
            if n in seen:
                print(f"DUPLICATE in {name}: {n} = {seen[n]} then {v}")
            seen[n] = v
            if isinstance(v,str) and ('localhost' in v or '127.0.0.1' in v):
                print(f"LOCALHOST in {name}: {n} = {v}")
EOF

