kubectl exec -n astronomy-shop deploy/product-reviews -- python3 -c "
import urllib.request, json, uuid
base='http://frontend-proxy:8080'
sid=str(uuid.uuid4())
def call(path, data=None, method=None):
    req=urllib.request.Request(base+path, data=json.dumps(data).encode() if data else None, method=method or ('POST' if data else 'GET'), headers={'Content-Type':'application/json','Cookie':'session-id='+sid})
    return urllib.request.urlopen(req, timeout=20)
r=call('/api/products'); data=json.loads(r.read()); pid=data[0]['id']; print('product:', pid)
r=call('/api/cart', {'productId':pid,'quantity':2}); print('cart add:', r.status)
r=call('/api/cart'); cart=json.loads(r.read()); print('cart items:', cart.get('items'))
order={'userId':sid,'email':'test@example.com','address':{'streetAddress':'123 Main St','city':'Anytown','state':'CA','country':'USA','zipCode':'12345'},'userCurrency':'USD','creditCard':{'creditCardNumber':'4432-8015-6152-0454','creditCardExpirationYear':2027,'creditCardExpirationMonth':11,'creditCardCvv':123}}
try:
    r=call('/api/checkout', order); print('checkout:', r.status, r.read()[:200])
except Exception as e:
    print('checkout ERROR:', e)
"

